            if (pull) sources.push({ voltage: pull.voltage, resistance: pull.resistance + binding.cpu.resistance });
          }
          const groundConductance = sources.filter((load) => load.voltage === 0).reduce((sum, load) => sum + 1 / load.resistance, 0);
